mq//+------------------------------------------------------------------+
//| Recalculate Buffers — FIXED DLL (v14.33)                        |
//+------------------------------------------------------------------+
void RecalculateBuffers()
{
   // DLL is ALWAYS daily (from PriorDayClose), never trailing
   Buffer_DLL      = CurrentEquity - (PriorDayClose - DLL_FixedAmount);
   Buffer_DLL_Pct  = (DLL_FixedAmount > 0.0) ? Buffer_DLL / DLL_FixedAmount * 100.0 : 0.0;

   // TLL (static or trailing depending on AccountType)
   if(TLL_IsTrailing)
   {
      double temp = HighWaterMark - TLL_FixedAmount;
      TLL_BreachLevel = MathMax(TLL_LockFloor, temp);   // never below InitBal
      Buffer_TLL      = CurrentEquity - TLL_BreachLevel;
   }
   else
   {
      Buffer_TLL = CurrentEquity - TLL_BreachLevel;     // static floor
   }
   Buffer_TLL_Pct = (TLL_FixedAmount > 0.0) ? Buffer_TLL / TLL_FixedAmount * 100.0 : 0.0;

   // Effective binding constraint (what the warning uses)
   if(Buffer_DLL <= Buffer_TLL)
   {
      Buffer_Effective     = Buffer_DLL;
      Buffer_Effective_Pct = Buffer_DLL_Pct;
      TLL_IsBinding        = false;
   }
   else
   {
      Buffer_Effective     = Buffer_TLL;
      Buffer_Effective_Pct = Buffer_TLL_Pct;
      TLL_IsBinding        = true;
   }

   // TF Shield (also daily, same logic as DLL)
   if(EnableTFShield)
   {
      double tf_fixed = WorkingAccountSize * Runtime_TFShieldPercentage / 100.0;
      Buffer_TF       = CurrentEquity - (PriorDayClose - tf_fixed);
      Buffer_TF_Pct   = (tf_fixed > 0.0) ? Buffer_TF / tf_fixed * 100.0 : 0.0;
   }
   else
   {
      Buffer_TF = Buffer_TF_Pct = 0.0;
   }
}
