//| v14.33 DLL Buffer Fix                                            |
//+------------------------------------------------------------------+
void RecalculateLimits()
{
   DLL_FixedAmount = WorkingAccountSize * Runtime_DailyLossLimitPct / 100.0;
   TLL_FixedAmount = WorkingAccountSize * Runtime_MaxTrailingDDPct / 100.0;

   DLL_BreachLevel = PriorDayClose - DLL_FixedAmount;

   if(TLL_IsTrailing)
      TLL_BreachLevel = MathMax(TLL_LockFloor, HighWaterMark - TLL_FixedAmount);
   else
      TLL_BreachLevel = TLL_LockFloor - TLL_FixedAmount;

   TFShieldLimit = WorkingAccountSize * Runtime_TFShieldPercentage / 100.0;
}

//+------------------------------------------------------------------+
//| v14.33 Corrected Buffer Calculation (fixes false DLL alerts)    |
//+------------------------------------------------------------------+
void RecalculateBuffers()
{
   // DLL is ALWAYS calculated from PriorDayClose (daily reset)
   Buffer_DLL      = CurrentEquity - (PriorDayClose - DLL_FixedAmount);
   Buffer_DLL_Pct  = (DLL_FixedAmount > 0.0) ? (Buffer_DLL / DLL_FixedAmount * 100.0) : 0.0;

   // TLL (trailing or static)
   if(TLL_IsTrailing)
   {
      double temp = HighWaterMark - TLL_FixedAmount;
      TLL_BreachLevel = MathMax(TLL_LockFloor, temp);
      Buffer_TLL      = CurrentEquity - TLL_BreachLevel;
   }
   else
      Buffer_TLL = CurrentEquity - TLL_BreachLevel;

   Buffer_TLL_Pct = (TLL_FixedAmount > 0.0) ? (Buffer_TLL / TLL_FixedAmount * 100.0) : 0.0;

   // Effective binding constraint for warnings
   if(Buffer_DLL <= Buffer_TLL)
   {
      Buffer_Effective     = Buffer_DLL;
      Buffer_Effective_Pct = Buffer_DLL_Pct;
      TLL_IsBinding        = false;
   }
   else
   {
      Buffer_Effective     = Buffer_TLL;
      Buffer_Effective_Pct = Buffer_TLL_Pct;
      TLL_IsBinding        = true;
   }

   // TF Shield (daily)
   if(EnableTFShield)
   {
      double tf_fixed = WorkingAccountSize * Runtime_TFShieldPercentage / 100.0;
      Buffer_TF       = CurrentEquity - (PriorDayClose - tf_fixed);
      Buffer_TF_Pct   = (tf_fixed > 0.0) ? (Buffer_TF / tf_fixed * 100.0) : 0.0;
   }
   else
      Buffer_TF = Buffer_TF_Pct = 0.0;
}

