   double l = iLow(_Symbol, PERIOD_CURRENT, idx);
   for(int j = 1; j <= strength; j++)
   {
      if(iLow(_Symbol, PERIOD_CURRENT, idx + j) <= l) return false;  // left / older
      if(iLow(_Symbol, PERIOD_CURRENT, idx - j) <= l) return false;  // right / newer
   }
