//+------------------------------------------------------------------+
//| Dynamic Panel Update — called every tick to refresh values       |
//+------------------------------------------------------------------+
void UpdateRiskPanel()
{
   if(!ShowRiskPanel) return;

   // ── ACCOUNT ───────────────────────────────────────────────────────
   ObjectSetString (0, "ACC_EQUITY_VAL",  "$" + DoubleToString(CurrentEquity, 2));

   color gainColor = (TodaysTotalGain >= 0) ? clrLime : clrRed;
   ObjectSetString (0, "ACC_DGAIN_VAL",   (TodaysTotalGain >= 0 ? "+$" : "-$") + DoubleToString(MathAbs(TodaysTotalGain), 2));
   ObjectSetInteger(0, "ACC_DGAIN_VAL",   OBJPROP_COLOR, gainColor);

   double totalGain = CurrentEquity - WorkingAccountSize;
   color  tgColor   = (totalGain >= 0) ? clrLime : clrRed;
   ObjectSetString (0, "ACC_TGAIN_VAL",   (totalGain >= 0 ? "+$" : "-$") + DoubleToString(MathAbs(totalGain), 2));
   ObjectSetInteger(0, "ACC_TGAIN_VAL",   OBJPROP_COLOR, tgColor);

   double dgt_level = PriorDayClose + Runtime_DailyGainTarget;
   double ttg_level = WorkingAccountSize * (1.0 + Runtime_TotalTargetGainPct / 100.0);
   DistToDGT = dgt_level - CurrentEquity;
   DistToTTG = ttg_level - CurrentEquity;

   ObjectSetString (0, "ACC_DGT_VAL",     "$" + DoubleToString(dgt_level, 2));
   color dgtColor = (DistToDGT <= 0) ? clrLime : clrOrange;
   ObjectSetString (0, "ACC_DISTDGT_VAL", (DistToDGT <= 0 ? "✓ " : "") + "$" + DoubleToString(MathAbs(DistToDGT), 2));
   ObjectSetInteger(0, "ACC_DISTDGT_VAL", OBJPROP_COLOR, dgtColor);

   ObjectSetString (0, "ACC_TTG_VAL",     "$" + DoubleToString(ttg_level, 2));
   color ttgColor = (DistToTTG <= 0) ? clrLime : clrOrange;
   ObjectSetString (0, "ACC_DISTTTG_VAL", (DistToTTG <= 0 ? "✓ " : "") + "$" + DoubleToString(MathAbs(DistToTTG), 2));
   ObjectSetInteger(0, "ACC_DISTTTG_VAL", OBJPROP_COLOR, ttgColor);

   // ── LIMITATIONS ───────────────────────────────────────────────────
   ObjectSetString(0, "LIM_DLL_VAL", "$" + DoubleToString(DLL_FixedAmount, 2));
   ObjectSetString(0, "LIM_TLL_VAL", "$" + DoubleToString(TLL_FixedAmount, 2));
   ObjectSetString(0, "LIM_TFS_VAL", "$" + DoubleToString(TFShieldLimit,   2));

   // ── RISKS / BUFFERS ───────────────────────────────────────────────
   color dllBufColor = (Buffer_DLL_Pct > 50) ? clrLime : (Buffer_DLL_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_DLLBUF_VAL", "$" + DoubleToString(Buffer_DLL, 2) + " (" + DoubleToString(Buffer_DLL_Pct, 0) + "%)");
   ObjectSetInteger(0, "RISK_DLLBUF_VAL", OBJPROP_COLOR, dllBufColor);

   color tllBufColor = (Buffer_TLL_Pct > 50) ? clrLime : (Buffer_TLL_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_TLLBUF_VAL", "$" + DoubleToString(Buffer_TLL, 2) + " (" + DoubleToString(Buffer_TLL_Pct, 0) + "%)");
   ObjectSetInteger(0, "RISK_TLLBUF_VAL", OBJPROP_COLOR, tllBufColor);

   color tfsBufColor = (Buffer_TF_Pct > 50) ? clrLime : (Buffer_TF_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_TFSBUF_VAL", "$" + DoubleToString(Buffer_TF, 2) + " (" + DoubleToString(Buffer_TF_Pct, 0) + "%)");
   ObjectSetInteger(0, "RISK_TFSBUF_VAL", OBJPROP_COLOR, tfsBufColor);

   string effTag    = TLL_IsBinding ? " [TLL]" : " [DLL]";
   color  effColor  = (Buffer_Effective_Pct > 50) ? clrLime : (Buffer_Effective_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_EFF_VAL", "$" + DoubleToString(Buffer_Effective, 2) + " (" + DoubleToString(Buffer_Effective_Pct, 0) + "%)" + effTag);
   ObjectSetInteger(0, "RISK_EFF_VAL", OBJPROP_COLOR, effColor);

   ObjectSetString (0, "RISK_EXP_VAL",   "$" + DoubleToString(RiskExposure, 2));
   double dll_vs_sl = DLL_FixedAmount - RiskExposure;
   color  dvColor   = (dll_vs_sl > 0) ? clrLime : clrRed;
   ObjectSetString (0, "RISK_DVSSL_VAL", "$" + DoubleToString(dll_vs_sl, 2));
   ObjectSetInteger(0, "RISK_DVSSL_VAL", OBJPROP_COLOR, dvColor);

   // ── OPEN POSITIONS — dynamic lines ────────────────────────────────
   int s_row = (int)(20 * Runtime_GuiScale);
   int pos_x = PanelOffsetX + (int)(8 * Runtime_GuiScale);
   int pos_y = Runtime_PanelBottomY + s_row;

   // Clear old position lines
   ObjectsDeleteAll(0, "MON_PL_");

   int shown = 0;
   for(int i = PositionsTotal()-1; i >= 0 && shown < 8; i--)
   {
      ulong tk = PositionGetTicket(i);
      if(tk <= 0 || PositionGetString(POSITION_SYMBOL) != _Symbol) continue;
      if(!PositionSelectByTicket(tk)) continue;

      string dir   = (PositionGetInteger(POSITION_TYPE)==POSITION_TYPE_BUY) ? "B" : "S";
      string lots  = DoubleToString(PositionGetDouble(POSITION_VOLUME), 2);
      double pl    = PositionGetDouble(POSITION_PROFIT);
      double sl_p  = PositionGetDouble(POSITION_SL);
      string sl_s  = (sl_p > 0) ? "SL:" + DoubleToString(sl_p, 1) : "no SL";
      string pl_s  = (pl >= 0 ? "+$" : "-$") + DoubleToString(MathAbs(pl), 2);
      string lname = "MON_PL_" + IntegerToString(shown);

      color plColor = (pl >= 0) ? clrLime : clrRed;
      CreatePanelLabel(lname+"_D", "#"+IntegerToString(tk)+" "+dir, pos_x,      pos_y, clrSilver, 8);
      CreatePanelLabel(lname+"_L", lots+" lots",                    pos_x+90,   pos_y, clrWhite,  8);
      CreatePanelLabel(lname+"_S", sl_s,                            pos_x+160,  pos_y, clrOrange, 8);
      CreatePanelLabel(lname+"_P", pl_s,                            pos_x+230,  pos_y, plColor,   8);
      pos_y += s_row;
      shown++;
   }
   if(shown == 0)
      CreatePanelLabel("MON_PL_NONE", "No open positions", pos_x, pos_y, clrDimGray, 8);

   ChartRedraw();
}

