//+------------------------------------------------------------------+
//| Panel Helper — Label                                             |
//+------------------------------------------------------------------+
void CreatePanelLabel(string name, string txt, int x, int y, color clr, int fsize=9, bool bold=false)
{
   if(ObjectFind(0,name)<0)
   {
      ObjectCreate(0,name,OBJ_LABEL,0,0,0);
      ObjectSetInteger(0,name,OBJPROP_CORNER,CORNER_LEFT_UPPER);
      ObjectSetString (0,name,OBJPROP_FONT,"Segoe UI");
      ObjectSetInteger(0,name,OBJPROP_FONTSIZE,fsize);
      if(bold) ObjectSetString(0,name,OBJPROP_FONT,"Segoe UI Bold");
   }
   ObjectSetInteger(0,name,OBJPROP_XDISTANCE,x);
   ObjectSetInteger(0,name,OBJPROP_YDISTANCE,y);
   ObjectSetInteger(0,name,OBJPROP_COLOR,clr);
   ObjectSetString (0,name,OBJPROP_TEXT,txt);
}

//+------------------------------------------------------------------+
//| Panel Helper — Button                                            |
//+------------------------------------------------------------------+
void CreatePanelButton(string name, string txt, int x, int y, int w, int h, color bg, color txtclr)
{
   if(ObjectFind(0,name)<0)
   {
      ObjectCreate(0,name,OBJ_BUTTON,0,0,0);
      ObjectSetInteger(0,name,OBJPROP_CORNER,CORNER_LEFT_UPPER);
      ObjectSetString (0,name,OBJPROP_FONT,"Segoe UI");
      ObjectSetInteger(0,name,OBJPROP_FONTSIZE,9);
   }
   ObjectSetInteger(0,name,OBJPROP_XDISTANCE,x);
   ObjectSetInteger(0,name,OBJPROP_YDISTANCE,y);
   ObjectSetInteger(0,name,OBJPROP_XSIZE,w);
   ObjectSetInteger(0,name,OBJPROP_YSIZE,h);
   ObjectSetInteger(0,name,OBJPROP_BGCOLOR,bg);
   ObjectSetInteger(0,name,OBJPROP_COLOR,txtclr);
   ObjectSetString (0,name,OBJPROP_TEXT,txt);
}

//+------------------------------------------------------------------+
//| Panel Helper — Edit Box                                          |
//+------------------------------------------------------------------+
void CreatePanelEdit(string name, string txt, int x, int y, int w)
{
   if(ObjectFind(0,name)<0)
   {
      ObjectCreate(0,name,OBJ_EDIT,0,0,0);
      ObjectSetInteger(0,name,OBJPROP_CORNER,CORNER_LEFT_UPPER);
      ObjectSetString (0,name,OBJPROP_FONT,"Segoe UI");
      ObjectSetInteger(0,name,OBJPROP_FONTSIZE,9);
      ObjectSetInteger(0,name,OBJPROP_BGCOLOR,C'40,40,55');
      ObjectSetInteger(0,name,OBJPROP_COLOR,clrWhite);
   }
   ObjectSetInteger(0,name,OBJPROP_XDISTANCE,x);
   ObjectSetInteger(0,name,OBJPROP_YDISTANCE,y);
   ObjectSetInteger(0,name,OBJPROP_XSIZE,w);
   ObjectSetString (0,name,OBJPROP_TEXT,txt);
}

//+------------------------------------------------------------------+
//| Panel Helper — Section Header                                    |
//+------------------------------------------------------------------+
void CreatePanelHeader(string name, string txt, int x, int y, color clr)
{
   CreatePanelLabel(name, txt, x, y, clr, 10, true);
}

//+------------------------------------------------------------------+
//| Panel Helper — Info Row (label + value)                          |
//+------------------------------------------------------------------+
void CreatePanelInfo(string name, string label, string value, int x, int y, color valclr)
{
   int lbl_w = (int)(142 * Runtime_GuiScale);
   CreatePanelLabel(name+"_LBL", label+":", x,          y, clrSilver);
   CreatePanelLabel(name+"_VAL", value,     x+lbl_w+16, y, valclr);
}

//+------------------------------------------------------------------+
