//+------------------------------------------------------------------+
//| Panel Helper — Label (font size always scales with GuiScale)     |
//+------------------------------------------------------------------+
void CreatePanelLabel(string name, string txt, int x, int y, color clr, int fsize=9, bool bold=false)
{
   if(ObjectFind(0,name)<0)
   {
      ObjectCreate(0,name,OBJ_LABEL,0,0,0);
      ObjectSetInteger(0,name,OBJPROP_CORNER,CORNER_LEFT_UPPER);
   }
   // Always update all properties so scaling takes effect immediately
   ObjectSetInteger(0,name,OBJPROP_XDISTANCE,x);
   ObjectSetInteger(0,name,OBJPROP_YDISTANCE,y);
   ObjectSetInteger(0,name,OBJPROP_COLOR,clr);
   ObjectSetInteger(0,name,OBJPROP_FONTSIZE,fsize);
   ObjectSetString (0,name,OBJPROP_FONT, bold ? "Segoe UI Bold" : "Segoe UI");
   ObjectSetString (0,name,OBJPROP_TEXT,txt);
}

//+------------------------------------------------------------------+
//| Panel Helper — Button (font size scales with GuiScale)           |
//+------------------------------------------------------------------+
void CreatePanelButton(string name, string txt, int x, int y, int w, int h, color bg, color txtclr, int fsize=9)
{
   if(ObjectFind(0,name)<0)
   {
      ObjectCreate(0,name,OBJ_BUTTON,0,0,0);
      ObjectSetInteger(0,name,OBJPROP_CORNER,CORNER_LEFT_UPPER);
   }
   ObjectSetInteger(0,name,OBJPROP_XDISTANCE,x);
   ObjectSetInteger(0,name,OBJPROP_YDISTANCE,y);
   ObjectSetInteger(0,name,OBJPROP_XSIZE,w);
   ObjectSetInteger(0,name,OBJPROP_YSIZE,h);
   ObjectSetInteger(0,name,OBJPROP_BGCOLOR,bg);
   ObjectSetInteger(0,name,OBJPROP_COLOR,txtclr);
   ObjectSetInteger(0,name,OBJPROP_FONTSIZE,fsize);
   ObjectSetString (0,name,OBJPROP_FONT,"Segoe UI Bold");
   ObjectSetString (0,name,OBJPROP_TEXT,txt);
}

//+------------------------------------------------------------------+
//| Panel Helper — Edit Box (font size scales with GuiScale)         |
//+------------------------------------------------------------------+
void CreatePanelEdit(string name, string txt, int x, int y, int w, int fsize=9)
{
   if(ObjectFind(0,name)<0)
   {
      ObjectCreate(0,name,OBJ_EDIT,0,0,0);
      ObjectSetInteger(0,name,OBJPROP_CORNER,CORNER_LEFT_UPPER);
      ObjectSetInteger(0,name,OBJPROP_BGCOLOR,C'40,40,55');
      ObjectSetInteger(0,name,OBJPROP_COLOR,clrWhite);
   }
   ObjectSetInteger(0,name,OBJPROP_XDISTANCE,x);
   ObjectSetInteger(0,name,OBJPROP_YDISTANCE,y);
   ObjectSetInteger(0,name,OBJPROP_XSIZE,w);
   ObjectSetInteger(0,name,OBJPROP_FONTSIZE,fsize);
   ObjectSetString (0,name,OBJPROP_FONT,"Segoe UI");
   ObjectSetString (0,name,OBJPROP_TEXT,txt);
}

//+------------------------------------------------------------------+
//| Panel Helper — Section Header                                    |
//+------------------------------------------------------------------+
void CreatePanelHeader(string name, string txt, int x, int y, color clr, int fsize=10)
{
   CreatePanelLabel(name, txt, x, y, clr, fsize, true);
}

//+------------------------------------------------------------------+
//| Panel Helper — Info Row (label + value, with scaling)            |
//+------------------------------------------------------------------+
void CreatePanelInfo(string name, string label, string value, int x, int y, color valclr, int lbl_w=118, int fsize=9)
{
   CreatePanelLabel(name+"_LBL", label+":", x,          y, clrSilver, fsize);
   CreatePanelLabel(name+"_VAL", value,     x+lbl_w+16, y, valclr,    fsize);
}

//+------------------------------------------------------------------+
//| Panel Helper — Open Position Line                                |
//+------------------------------------------------------------------+
void CreatePanelPosLine(string name, string ticket, string lots, string sl, string tp, int x, int y)
{
   int fsz = (int)(8 * Runtime_GuiScale);
   CreatePanelLabel(name+"_T", ticket, x,     y, clrRed,    fsz);
   CreatePanelLabel(name+"_L", lots,   x+130, y, clrWhite,  fsz);
   CreatePanelLabel(name+"_S", sl,     x+175, y, clrOrange, fsz);
   CreatePanelLabel(name+"_P", tp,     x+235, y, clrWhite,  fsz);
}

//+------------------------------------------------------------------+
//| Dynamic Panel Update — called every tick to refresh values       |
//+------------------------------------------------------------------+
void UpdateRiskPanel()
{
   if(!ShowRiskPanel) return;

   int fsz = (int)(9 * Runtime_GuiScale);

   // ── ACCOUNT ───────────────────────────────────────────────────────
   ObjectSetString (0, "ACC_EQUITY_VAL",  OBJPROP_TEXT, "$" + DoubleToString(CurrentEquity, 2));
   ObjectSetInteger(0, "ACC_EQUITY_VAL",  OBJPROP_FONTSIZE, fsz);

   color gainColor = (TodaysTotalGain >= 0) ? clrLime : clrRed;
   ObjectSetString (0, "ACC_DGAIN_VAL",   OBJPROP_TEXT, (TodaysTotalGain >= 0 ? "+$" : "-$") + DoubleToString(MathAbs(TodaysTotalGain), 2));
   ObjectSetInteger(0, "ACC_DGAIN_VAL",   OBJPROP_COLOR, gainColor);
   ObjectSetInteger(0, "ACC_DGAIN_VAL",   OBJPROP_FONTSIZE, fsz);

   double totalGain = CurrentEquity - WorkingAccountSize;
   color  tgColor   = (totalGain >= 0) ? clrLime : clrRed;
   ObjectSetString (0, "ACC_TGAIN_VAL",   OBJPROP_TEXT, (totalGain >= 0 ? "+$" : "-$") + DoubleToString(MathAbs(totalGain), 2));
   ObjectSetInteger(0, "ACC_TGAIN_VAL",   OBJPROP_COLOR, tgColor);
   ObjectSetInteger(0, "ACC_TGAIN_VAL",   OBJPROP_FONTSIZE, fsz);

   double dgt_level = PriorDayClose + Runtime_DailyGainTarget;
   double ttg_level = WorkingAccountSize * (1.0 + Runtime_TotalTargetGainPct / 100.0);
   DistToDGT = dgt_level - CurrentEquity;
   DistToTTG = ttg_level - CurrentEquity;

   ObjectSetString (0, "ACC_DGT_VAL",     OBJPROP_TEXT, "$" + DoubleToString(dgt_level, 2));
   ObjectSetInteger(0, "ACC_DGT_VAL",     OBJPROP_FONTSIZE, fsz);

   color dgtColor = (DistToDGT <= 0) ? clrLime : clrOrange;
   ObjectSetString (0, "ACC_DISTDGT_VAL", OBJPROP_TEXT, (DistToDGT <= 0 ? "✓ " : "") + "$" + DoubleToString(MathAbs(DistToDGT), 2));
   ObjectSetInteger(0, "ACC_DISTDGT_VAL", OBJPROP_COLOR, dgtColor);
   ObjectSetInteger(0, "ACC_DISTDGT_VAL", OBJPROP_FONTSIZE, fsz);

   ObjectSetString (0, "ACC_TTG_VAL",     OBJPROP_TEXT, "$" + DoubleToString(ttg_level, 2));
   ObjectSetInteger(0, "ACC_TTG_VAL",     OBJPROP_FONTSIZE, fsz);

   color ttgColor = (DistToTTG <= 0) ? clrLime : clrOrange;
   ObjectSetString (0, "ACC_DISTTTG_VAL", OBJPROP_TEXT, (DistToTTG <= 0 ? "✓ " : "") + "$" + DoubleToString(MathAbs(DistToTTG), 2));
   ObjectSetInteger(0, "ACC_DISTTTG_VAL", OBJPROP_COLOR, ttgColor);
   ObjectSetInteger(0, "ACC_DISTTTG_VAL", OBJPROP_FONTSIZE, fsz);

   // ── LIMITATIONS ───────────────────────────────────────────────────
   ObjectSetString (0, "LIM_DLL_VAL", OBJPROP_TEXT, "$" + DoubleToString(DLL_FixedAmount, 2));
   ObjectSetInteger(0, "LIM_DLL_VAL", OBJPROP_FONTSIZE, fsz);
   ObjectSetString (0, "LIM_TLL_VAL", OBJPROP_TEXT, "$" + DoubleToString(TLL_FixedAmount, 2));
   ObjectSetInteger(0, "LIM_TLL_VAL", OBJPROP_FONTSIZE, fsz);
   ObjectSetString (0, "LIM_TFS_VAL", OBJPROP_TEXT, "$" + DoubleToString(TFShieldLimit,   2));
   ObjectSetInteger(0, "LIM_TFS_VAL", OBJPROP_FONTSIZE, fsz);

   // ── RISKS / BUFFERS ───────────────────────────────────────────────
   color dllBufColor = (Buffer_DLL_Pct > 50) ? clrLime : (Buffer_DLL_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_DLLBUF_VAL", OBJPROP_TEXT, "$" + DoubleToString(Buffer_DLL, 2) + " (" + DoubleToString(Buffer_DLL_Pct, 0) + "%)");
   ObjectSetInteger(0, "RISK_DLLBUF_VAL", OBJPROP_COLOR, dllBufColor);
   ObjectSetInteger(0, "RISK_DLLBUF_VAL", OBJPROP_FONTSIZE, fsz);

   color tllBufColor = (Buffer_TLL_Pct > 50) ? clrLime : (Buffer_TLL_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_TLLBUF_VAL", OBJPROP_TEXT, "$" + DoubleToString(Buffer_TLL, 2) + " (" + DoubleToString(Buffer_TLL_Pct, 0) + "%)");
   ObjectSetInteger(0, "RISK_TLLBUF_VAL", OBJPROP_COLOR, tllBufColor);
   ObjectSetInteger(0, "RISK_TLLBUF_VAL", OBJPROP_FONTSIZE, fsz);

   color tfsBufColor = (Buffer_TF_Pct > 50) ? clrLime : (Buffer_TF_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_TFSBUF_VAL", OBJPROP_TEXT, "$" + DoubleToString(Buffer_TF, 2) + " (" + DoubleToString(Buffer_TF_Pct, 0) + "%)");
   ObjectSetInteger(0, "RISK_TFSBUF_VAL", OBJPROP_COLOR, tfsBufColor);
   ObjectSetInteger(0, "RISK_TFSBUF_VAL", OBJPROP_FONTSIZE, fsz);

   string effTag   = TLL_IsBinding ? " [TLL]" : " [DLL]";
   color  effColor = (Buffer_Effective_Pct > 50) ? clrLime : (Buffer_Effective_Pct > 20) ? clrOrange : clrRed;
   ObjectSetString (0, "RISK_EFF_VAL", OBJPROP_TEXT, "$" + DoubleToString(Buffer_Effective, 2) + " (" + DoubleToString(Buffer_Effective_Pct, 0) + "%)" + effTag);
   ObjectSetInteger(0, "RISK_EFF_VAL", OBJPROP_COLOR, effColor);
   ObjectSetInteger(0, "RISK_EFF_VAL", OBJPROP_FONTSIZE, fsz);

   ObjectSetString (0, "RISK_EXP_VAL",   OBJPROP_TEXT, "$" + DoubleToString(RiskExposure, 2));
   ObjectSetInteger(0, "RISK_EXP_VAL",   OBJPROP_FONTSIZE, fsz);

   double dll_vs_sl = DLL_FixedAmount - RiskExposure;
   color  dvColor   = (dll_vs_sl >= 0) ? clrLime : clrRed;
   ObjectSetString (0, "RISK_DVSSL_VAL", OBJPROP_TEXT, "$" + DoubleToString(dll_vs_sl, 2));
   ObjectSetInteger(0, "RISK_DVSSL_VAL", OBJPROP_COLOR, dvColor);
   ObjectSetInteger(0, "RISK_DVSSL_VAL", OBJPROP_FONTSIZE, fsz);

   // ── OPEN POSITIONS — dynamic lines ────────────────────────────────
   int s_row = (int)(20 * Runtime_GuiScale);
   int pos_fsz = (int)(8 * Runtime_GuiScale);
   int pos_x = PanelOffsetX + (int)(8 * Runtime_GuiScale);
   int pos_y = Runtime_PanelBottomY + s_row;

   // Clear old position lines
   ObjectsDeleteAll(0, "MON_PL_");

   int shown = 0;
   for(int i = PositionsTotal()-1; i >= 0 && shown < 8; i--)
   {
      ulong tk = PositionGetTicket(i);
      if(tk <= 0 || PositionGetString(POSITION_SYMBOL) != _Symbol) continue;
      if(!PositionSelectByTicket(tk)) continue;

      string dir  = (PositionGetInteger(POSITION_TYPE)==POSITION_TYPE_BUY) ? "B" : "S";
      string lots = DoubleToString(PositionGetDouble(POSITION_VOLUME), 2);
      double pl   = PositionGetDouble(POSITION_PROFIT);
      double sl_p = PositionGetDouble(POSITION_SL);
      string sl_s = (sl_p > 0) ? "SL:" + DoubleToString(sl_p, 1) : "no SL";
      string pl_s = (pl >= 0 ? "+$" : "-$") + DoubleToString(MathAbs(pl), 2);
      string lname = "MON_PL_" + IntegerToString(shown);

      color plColor = (pl >= 0) ? clrLime : clrRed;
      CreatePanelLabel(lname+"_D", "#"+IntegerToString(tk)+" "+dir, pos_x,     pos_y, clrSilver, pos_fsz);
      CreatePanelLabel(lname+"_L", lots+" lots",                    pos_x+90,  pos_y, clrWhite,  pos_fsz);
      CreatePanelLabel(lname+"_S", sl_s,                            pos_x+155, pos_y, clrOrange, pos_fsz);
      CreatePanelLabel(lname+"_P", pl_s,                            pos_x+215, pos_y, plColor,   pos_fsz);
      pos_y += s_row;
      shown++;
   }
   if(shown == 0)
      CreatePanelLabel("MON_PL_NONE", "No open positions", pos_x, pos_y, clrDimGray, pos_fsz);

   ChartRedraw();
}

