   ObjectSetInteger(0, "ACC_DISTDGT_VAL", OBJPROP_COLOR, dgtColor);
   ObjectSetInteger(0, "ACC_DISTDGT_VAL", OBJPROP_FONTSIZE, fsz);

   ObjectSetString (0, "ACC_TTG_VAL",     OBJPROP_TEXT, "$" + DoubleToString(ttg_level, 2));
