//+------------------------------------------------------------------+
//| Panel Helper — Open Position Row                                 |
//+------------------------------------------------------------------+
void CreatePanelPosLine(string name, string ticket, string lots, string sl, string tp, int x, int y)
{
   int fsz = (int)MathRound(8 * Runtime_GuiScale);
   CreatePanelLabel(name+"_T", ticket, x,     y, clrRed,    fsz, false);
