void CreateTransparentPanel()
{
   if(!ShowRiskPanel) return;

   // ── Full teardown — wipe every panel object so scale changes take full effect ──
   ObjectsDeleteAll(0, "TF_");
   ObjectsDeleteAll(0, "BTN_FlattenAll"); ObjectsDeleteAll(0, "BTN_Settings");
   ObjectsDeleteAll(0, "BTN_BE_ALL");     ObjectsDeleteAll(0, "BTN_KillSwitch");
   ObjectsDeleteAll(0, "BTN_SmartBuy");   ObjectsDeleteAll(0, "BTN_SmartSell");
   ObjectsDeleteAll(0, "BTN_MODE");
   ObjectsDeleteAll(0, "LBL_");
   ObjectsDeleteAll(0, "HDR_");
   ObjectsDeleteAll(0, "ACC_");
   ObjectsDeleteAll(0, "LIM_");
   ObjectsDeleteAll(0, "RISK_");
   ObjectsDeleteAll(0, "GUI_EDIT_");
   ObjectsDeleteAll(0, "EDIT_TRAIL_");
   ObjectsDeleteAll(0, "MON_PL_");

   double s    = Runtime_GuiScale;
   int x       = PanelOffsetX;
   int y       = PanelOffsetY;
   int pad     = (int)(8  * s);
   int row     = (int)(22 * s);    // uniform row height (Grok standard)
   int lbl_w   = (int)(130 * s);   // label column — values always start at x+pad+lbl_w+8
   int val_x   = x + pad + lbl_w + 8;

   int fsz_title = (int)MathRound(11 * s);
   int fsz_hdr   = (int)MathRound(10 * s);
   int fsz_body  = (int)MathRound(9  * s);

   int panel_w = (int)(310 * s);   // wide enough for all content at any scale
   int panel_h = (int)(900 * s);   // trimmed after content

   // ── Background ────────────────────────────────────────────────────
   string bg = "TF_MAIN_BG";
   ObjectCreate(0, bg, OBJ_RECTANGLE_LABEL, 0, 0, 0);
   ObjectSetInteger(0, bg, OBJPROP_CORNER,      CORNER_LEFT_UPPER);
   ObjectSetInteger(0, bg, OBJPROP_BGCOLOR,     C'32,34,52');
   ObjectSetInteger(0, bg, OBJPROP_BORDER_TYPE, BORDER_FLAT);
   ObjectSetInteger(0, bg, OBJPROP_COLOR,       C'80,90,130');
   ObjectSetInteger(0, bg, OBJPROP_WIDTH,       1);
   ObjectSetInteger(0, bg, OBJPROP_BACK,        true);
   ObjectSetInteger(0, bg, OBJPROP_XDISTANCE,   x - pad);
   ObjectSetInteger(0, bg, OBJPROP_YDISTANCE,   y - pad);
   ObjectSetInteger(0, bg, OBJPROP_XSIZE,       panel_w);
   ObjectSetInteger(0, bg, OBJPROP_YSIZE,       panel_h);

   y += pad;

   // ── Title ─────────────────────────────────────────────────────────
   CreatePanelLabel("TF_TITLE", "TF RiskManager v14.34", x+pad, y, clrCyan, fsz_title, true);
   y += row + 6;

   // ── Row 1: FLATTEN ALL | SETTINGS ────────────────────────────────
   int btn_h = (int)(26 * s);
   int big_w = (int)(130 * s);    // wide enough for "FLATTEN ALL"
   CreatePanelButton("BTN_FlattenAll", "FLATTEN ALL", x+pad,          y, big_w, btn_h, clrMaroon,    clrWhite, fsz_body);
   CreatePanelButton("BTN_Settings",   "SETTINGS",    x+pad+big_w+8,  y, big_w, btn_h, C'55,55,78',  clrWhite, fsz_body);
   y += btn_h + 6;

   // ── Row 2: BE ALL | E-STOP ────────────────────────────────────────
   CreatePanelButton("BTN_BE_ALL",     "BE ALL",      x+pad,          y, big_w, btn_h, C'0,110,220', clrWhite, fsz_body);
   CreatePanelButton("BTN_KillSwitch", "E-STOP",      x+pad+big_w+8,  y, big_w, btn_h, C'175,20,20', clrWhite, fsz_body);
   y += btn_h + 6;

   // ── Row 3: BUY | SELL | MARKET ───────────────────────────────────
   int sm_w  = (int)(62 * s);
   int mkt_w = (int)(80 * s);    // wide enough for "MARKET"
   CreatePanelButton("BTN_SmartBuy",  "BUY",    x+pad,              y, sm_w,  btn_h, clrLime, clrBlack, fsz_body);
   CreatePanelButton("BTN_SmartSell", "SELL",   x+pad+sm_w+6,       y, sm_w,  btn_h, clrRed,  clrWhite, fsz_body);
   CreatePanelButton("BTN_MODE",      "MARKET", x+pad+2*sm_w+12,    y, mkt_w, btn_h, clrGold, clrBlack, fsz_body);
   y += btn_h + 8;

   // Input rows — label left, edit box right (consistent val_x column)
   int edit_w = (int)(64 * s);

   // ── Row 4: Size (lots) ────────────────────────────────────────────
   CreatePanelLabel("LBL_SIZE", "Size (lots):", x+pad, y, clrSilver, fsz_body, false);
   CreatePanelEdit ("GUI_EDIT_Size", DoubleToString(Runtime_FixedLotSize, 2), val_x, y, edit_w);
   y += row;

   // ── Row 5: SL (pips) ─────────────────────────────────────────────
   CreatePanelLabel("LBL_SL", "SL (pips):", x+pad, y, clrSilver, fsz_body, false);
   CreatePanelEdit ("GUI_EDIT_SL", IntegerToString(Runtime_SL_Pips), val_x, y, edit_w);
   y += row;

   // ── Row 6: TP (pips) ─────────────────────────────────────────────
   CreatePanelLabel("LBL_TP", "TP (pips):", x+pad, y, clrSilver, fsz_body, false);
   CreatePanelEdit ("GUI_EDIT_TP", IntegerToString(Runtime_TP_Pips), val_x, y, edit_w);
   y += row;

   // ── Row 7: Trail Dist | Trail Act (same row, two mini-columns) ────
   int th_lbl = (int)(86 * s);   // half-row label width
   int th_edit= (int)(46 * s);   // half-row edit width
   int col2_x = x + pad + th_lbl + th_edit + (int)(10 * s);
   CreatePanelLabel("LBL_TRAIL_D", "Trail (pips):", x+pad,               y, clrSilver, fsz_body, false);
   CreatePanelEdit ("EDIT_TRAIL_D", IntegerToString(Runtime_TrailingDistance),   x+pad+th_lbl+4, y, th_edit);
   CreatePanelLabel("LBL_TRAIL_A", "Act:",           col2_x,              y, clrSilver, fsz_body, false);
   CreatePanelEdit ("EDIT_TRAIL_A", IntegerToString(Runtime_TrailingActivation), col2_x+(int)(28*s), y, th_edit);
   y += row + 10;

   // ── ACCOUNT ───────────────────────────────────────────────────────
   CreatePanelHeader("HDR_ACC", "ACCOUNT", x+pad, y, clrYellow, fsz_hdr);
   y += row;
   CreatePanelInfo("ACC_EQUITY",  "Equity",      "$0.00", x+pad, y, clrWhite,  lbl_w, fsz_body); y += row;
