 485: //+------------------------------------------------------------------+
 486: //| v14.20 ZZ-04: ZZ_IsPivotHigh                                     |
 487: //| True when bar[idx] is the highest High in a ±strength window.    |
 488: //| Mirrors Sierra Chart "Number of Bars for High" parameter.        |
 489: //| MQL5 index convention: idx=0 is current bar (rightmost),         |
 490: //| idx+j = older bars (left on chart), idx-j = newer (right).       |
 491: //+------------------------------------------------------------------+
 492: bool ZZ_IsPivotHigh(int idx, int strength)
 493: {
 494:    if(idx < strength) return false;   // need strength confirmed bars to the right
 495:    double h = iHigh(_Symbol, PERIOD_CURRENT, idx);
 496:    for(int j = 1; j <= strength; j++)
 497:    {
 498:       if(iHigh(_Symbol, PERIOD_CURRENT, idx + j) >= h) return false;  // left / older
 499:       if(iHigh(_Symbol, PERIOD_CURRENT, idx - j) >= h) return false;  // right / newer
 500:    }
 501:    return true;
 502: }
 503: 
 504: //+------------------------------------------------------------------+
 505: //| v14.20 ZZ-05: ZZ_IsPivotLow                                      |
 506: //| True when bar[idx] is the lowest Low in a ±strength window.      |
 507: //+------------------------------------------------------------------+
 508: bool ZZ_IsPivotLow(int idx, int strength)
 509: {
 510:    if(idx < strength) return false;
 511:    double l = iLow(_Symbol, PERIOD_CURRENT, idx);
 512:    for(int j = 1; j <= strength; j++)
 513:    {
 514:       if(iLow(_Symbol, PERIOD_CURRENT, idx + j) <= l) return false;  // left / older
 515:       if(iLow(_Symbol, PERIOD_CURRENT, idx - j) <= l) return false;  // right / newer
 516:    }
 517:    return true;
 518: }
