 530: //+------------------------------------------------------------------+
 531: //| v14.20 ZZ-07: CalculateZigZag                                    |
 532: //| Pass 1 – scan for raw confirmed pivots (oldest bar → newest)     |
 533: //| Pass 2 – consolidate into strict alternating H/L sequence        |
 534: //| Pass 3 – delegate drawing to DrawZigZagLines()                   |
 535: //+------------------------------------------------------------------+
 536: void CalculateZigZag()
 537: {
 538:    if(!ZZ_Enabled) return;
 539: 
 540:    DeleteZigZagObjects();
 541: 
 542:    int total_bars = iBars(_Symbol, PERIOD_CURRENT);
 543:    if(total_bars < ZZ_Strength * 2 + 2) return;
 544: 
 545:    // scan_end  = most-recent bar we can fully confirm (needs strength bars to its right)
 546:    // scan_start= oldest bar in the lookback window
 547:    int scan_end   = ZZ_Strength;
 548:    int scan_start = (int)MathMin(ZZ_LookbackBars + ZZ_Strength,
 549:                                  total_bars - ZZ_Strength - 1);
 550: 
 551:    // ── Pass 1: collect raw pivots ──────────────────────────────────
 552:    ZZ_PivotPoint raw[];
 553:    int raw_count = 0;
 554: 
 555:    for(int i = scan_start; i >= scan_end; i--)
 556:    {
 557:       bool is_ph = ZZ_IsPivotHigh(i, ZZ_Strength);
 558:       bool is_pl = ZZ_IsPivotLow(i,  ZZ_Strength);
