 489: //| MQL5 index convention: idx=0 is current bar (rightmost),         |
 490: //| idx+j = older bars (left on chart), idx-j = newer (right).       |
 491: //+------------------------------------------------------------------+
 492: bool ZZ_IsPivotHigh(int idx, int strength)
 493: {
 494:    if(idx < strength) return false;   // need strength confirmed bars to the right
 495:    double h = iHigh(_Symbol, PERIOD_CURRENT, idx);
 496:    for(int j = 1; j <= strength; j++)
 497:    {
 498:       if(iHigh(_Symbol, PERIOD_CURRENT, idx + j) >= h) return false;  // left / older
 499:       if(iHigh(_Symbol, PERIOD_CURRENT, idx - j) >= h) return false;  // right / newer
