2286: void OnChartEvent(const int id, const long &lparam, const double &dparam, const string &sparam)
2287: {
2288:    // Handle draggable SL/TP lines
2289:    if(id == CHARTEVENT_OBJECT_DRAG)
2290:    {
2291:       if(StringFind(sparam, SL_LinePrefix) == 0 || StringFind(sparam, TP_LinePrefix) == 0)
2292:       {
2293:          // Do NOT force deselect immediately. Let the user drag.
2294:          // ObjectSetInteger(0, sparam, OBJPROP_SELECTED, false);
2295: 
2296:          static uint last_drag_time = 0;
2297:          if(GetTickCount() - last_drag_time < 200) return; // Throttle updates to 5Hz
2298:          last_drag_time = GetTickCount();
2299: 
2300:          double new_price = ObjectGetDouble(0, sparam, OBJPROP_PRICE);
2301:          bool is_sl = StringFind(sparam, SL_LinePrefix) == 0;
2302:          int prefix_len = is_sl ? StringLen(SL_LinePrefix) : StringLen(TP_LinePrefix);
2303:          ulong ticket = (ulong)StringToInteger(StringSubstr(sparam, prefix_len));
2304: 
2305:          int idx = -1;
2306:          for(int i = 0; i < monitor_count; i++)
2307:          {
2308:             if(monitored_positions[i].ticket == ticket)
2309:             {
2310:                idx = i;
2311:                break;
2312:             }
2313:          }
2314: 
2315:          if(idx < 0) return;
2316: 
2317:          double new_sl = is_sl ? new_price : PositionGetDouble(POSITION_SL);
2318:          double new_tp = is_sl ? PositionGetDouble(POSITION_TP) : new_price;
2319: 
2320:          // Only modify if price changed significantly
2321:          double current_sl = PositionGetDouble(POSITION_SL);
2322:          double current_tp = PositionGetDouble(POSITION_TP);
2323: 
2324:          if( (is_sl && MathAbs(new_sl - current_sl) > point_value) || (!is_sl && MathAbs(new_tp - current_tp) > point_value) )
2325:          {
2326:              if(ModifyPositionSLTP(ticket, new_sl, new_tp, "Manual drag " + (is_sl ? "SL" : "TP")))
2327:              {
2328:                 if(is_sl)
2329:                 {
2330:                    monitored_positions[idx].trailing_sl_price = new_price;
2331:                 }
2332:                 Print("Manual drag updated ", (is_sl ? "SL" : "TP"), " #", ticket, " to ", DoubleToString(new_price, _Digits));
2333:              }
2334:              else
2335:              {
2336:                  Print("Manual drag failed - reverting line");
2337:              }
2338:          }
2339: 
2340:          ChartRedraw();
2341:          return;
2342:       }
2343:    }
2344: 
