# ─── helper: find closing brace of function starting at start_1based ─────────
def func_end(lines, start_1based):
    depth, in_func = 0, False
    for i in range(start_1based - 1, len(lines)):
        for ch in lines[i]:
            if ch == '{':   depth += 1; in_func = True
            elif ch == '}':
                depth -= 1
                if in_func and depth == 0:
                    return i + 1  # 1-based inclusive
    return len(lines)

