NEW["OnChartEvent"] = '''\
void OnChartEvent(const int id, const long& lparam, const double& dparam, const string& sparam)
{
   // ── Draggable SL/TP lines ──────────────────────────────────────────────
   if(id == CHARTEVENT_OBJECT_DRAG)
   {
      if(StringFind(sparam, SL_LinePrefix) == 0 || StringFind(sparam, TP_LinePrefix) == 0)
      {
         static uint last_drag_time = 0;
         if(GetTickCount() - last_drag_time < 200) return;
         last_drag_time = GetTickCount();

         double new_price = ObjectGetDouble(0, sparam, OBJPROP_PRICE);
         bool   is_sl     = StringFind(sparam, SL_LinePrefix) == 0;
         int    pfx_len   = is_sl ? StringLen(SL_LinePrefix) : StringLen(TP_LinePrefix);
         ulong  ticket    = (ulong)StringToInteger(StringSubstr(sparam, pfx_len));

         int idx = -1;
         for(int i = 0; i < monitor_count; i++)
            if(monitored_positions[i].ticket == ticket) { idx = i; break; }
         if(idx < 0) return;

         if(!PositionSelectByTicket(ticket)) return;
         double new_sl = is_sl ? new_price : PositionGetDouble(POSITION_SL);
         double new_tp = is_sl ? PositionGetDouble(POSITION_TP) : new_price;
         double cur_sl = PositionGetDouble(POSITION_SL);
         double cur_tp = PositionGetDouble(POSITION_TP);

         if((is_sl && MathAbs(new_sl-cur_sl) > point_value) || (!is_sl && MathAbs(new_tp-cur_tp) > point_value))
         {
            if(ModifyPositionSLTP(ticket, new_sl, new_tp, "Manual drag " + (is_sl ? "SL" : "TP")))
            {
               if(is_sl) monitored_positions[idx].trailing_sl_price = new_price;
               Print("Manual drag updated ", (is_sl ? "SL" : "TP"), " #", ticket, " to ", DoubleToString(new_price, _Digits));
            }
            else Print("Manual drag failed - reverting line");
         }
         ChartRedraw();
         return;
      }
   }

   // ── Button click handlers ──────────────────────────────────────────────
   if(id == CHARTEVENT_OBJECT_CLICK)
   {
      // Track active edit to pause OnTick while user types
      if(ObjectGetInteger(0, sparam, OBJPROP_TYPE) == OBJ_EDIT)
         g_active_edit_object = sparam;   // intentionally no return

      if(sparam == "BTN_FlattenAll")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         CloseAllPositions("MANUAL FLATTEN");
         ChartRedraw();
         return;
      }
      if(sparam == "BTN_BE_ALL")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         MoveAllToBreakeven();
         return;
      }
      if(sparam == "BTN_Settings")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         if(SettingsPanelExpanded) SaveSettingsFromPanel();
         ToggleSettingsPanel();
         ChartRedraw();
         return;
      }
      if(sparam == "BTN_SmartBuy")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_SL_Pips = (int)StringToInteger(ObjectGetString(0, "GUI_EDIT_SL",   OBJPROP_TEXT));
         Runtime_TP_Pips = (int)StringToInteger(ObjectGetString(0, "GUI_EDIT_TP",   OBJPROP_TEXT));
         string _s = ObjectGetString(0, "GUI_EDIT_Size", OBJPROP_TEXT);
         if(StringLen(_s) > 0)
         {
            double _p=StringToDouble(_s), _mn=SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_MIN);
            double _mx=SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_MAX), _st=SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_STEP);
            if(_p>=_mn&&_p<=_mx) Runtime_FixedLotSize=MathFloor(_p/_st)*_st;
            else { Runtime_FixedLotSize=MathMax(_mn,MathMin(_mx,_p>0?_p:_mn));
                   ObjectSetString(0,"GUI_EDIT_Size",OBJPROP_TEXT,DoubleToString(Runtime_FixedLotSize,2)); }
         }
         ExecuteSmartEntry(ORDER_TYPE_BUY);
         return;
      }
      if(sparam == "BTN_SmartSell")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_SL_Pips = (int)StringToInteger(ObjectGetString(0, "GUI_EDIT_SL",   OBJPROP_TEXT));
         Runtime_TP_Pips = (int)StringToInteger(ObjectGetString(0, "GUI_EDIT_TP",   OBJPROP_TEXT));
         string _s = ObjectGetString(0, "GUI_EDIT_Size", OBJPROP_TEXT);
         if(StringLen(_s) > 0)
         {
            double _p=StringToDouble(_s), _mn=SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_MIN);
            double _mx=SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_MAX), _st=SymbolInfoDouble(_Symbol,SYMBOL_VOLUME_STEP);
            if(_p>=_mn&&_p<=_mx) Runtime_FixedLotSize=MathFloor(_p/_st)*_st;
            else { Runtime_FixedLotSize=MathMax(_mn,MathMin(_mx,_p>0?_p:_mn));
                   ObjectSetString(0,"GUI_EDIT_Size",OBJPROP_TEXT,DoubleToString(Runtime_FixedLotSize,2)); }
         }
         ExecuteSmartEntry(ORDER_TYPE_SELL);
         return;
      }
      if(StringFind(sparam, "BTN_Close_") == 0)
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         ulong ticket = (ulong)StringToInteger(StringSubstr(sparam, 10));
         ClosePositionAtMarket(ticket, "Manual Monitor Close");
         ChartRedraw();
         return;
      }
      if(sparam == "BTN_OrderMode")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_IsPendingMode = !Runtime_IsPendingMode;
         if(Runtime_IsPendingMode && Runtime_PendingPrice == 0)
            Runtime_PendingPrice = SymbolInfoDouble(_Symbol, SYMBOL_BID);
         CreateTransparentPanel();
         return;
      }
      if(sparam == "BTN_KillSwitch")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_EnableEmergencyStop = !Runtime_EnableEmergencyStop;
         if(Runtime_EnableEmergencyStop) { CloseAllPositions(); CancelAllPendingOrders(); }
         CreateTransparentPanel();
         return;
      }
      // ── Settings panel: toggle buttons (v14.12 direct handlers) ───────
      if(sparam == "SET_BTN_Monitor")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_EnableAutoClose = !Runtime_EnableAutoClose;
         UpdateSettingsPanel(); ChartRedraw(); return;
      }
      if(sparam == "SET_BTN_Trailing")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_TrailingEnabled = !Runtime_TrailingEnabled;
         for(int i = 0; i < monitor_count; i++)
            monitored_positions[i].trailing_enabled = Runtime_TrailingEnabled;
         UpdateSettingsPanel(); ChartRedraw(); return;
      }
      if(sparam == "SET_BTN_Time")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_UseTimeFilter = !Runtime_UseTimeFilter;
         UpdateSettingsPanel(); ChartRedraw(); return;
      }
      if(sparam == "SET_BTN_News")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_UseNewsFilter = !Runtime_UseNewsFilter;
         UpdateSettingsPanel(); ChartRedraw(); return;
      }
      if(sparam == "SET_BTN_ATR")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_UseATR = !Runtime_UseATR;
         UpdateSettingsPanel(); ChartRedraw(); return;
      }
      if(sparam == "SET_BTN_Scale")
      {
         ObjectSetInteger(0, sparam, OBJPROP_STATE, false);
         Runtime_UseAutoScaling = !Runtime_UseAutoScaling;
         if(Runtime_UseAutoScaling)
         {
            int dpi = TerminalInfoInteger(TERMINAL_SCREEN_DPI);
            Runtime_GuiScale = (dpi > 0) ? dpi / 96.0 : 1.0;
         }
         ObjectsDeleteAll(0);
         CreateTransparentPanel();
         UpdateMonitorGUI();
         if(SettingsPanelExpanded) { SettingsPanelExpanded = false; ToggleSettingsPanel(); }
         ChartRedraw();
         return;
      }
   }

   // ── Edit-box ENDEDIT handlers (v14.12 direct per-field) ───────────────
   if(id == CHARTEVENT_OBJECT_ENDEDIT)
   {
      if(sparam == "SET_EDIT_Risk")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) Runtime_RiskPerTradePct = v;
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_DLoss")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) { Runtime_DailyLossLimitPct = v; RecalculateLimits(); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_TLL")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) { Runtime_MaxTrailingDDPct = v; RecalculateLimits(); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_TFS")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) { Runtime_TFShieldPercentage = v; RecalculateLimits(); RecalculateBuffers(); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_DGain")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) { Runtime_DailyGainTargetPct = v; Runtime_DailyGainTarget = WorkingAccountSize * (v / 100.0); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_TTG")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) Runtime_TotalTargetGainPct = v;
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_PDC")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v >= 0) { Manual_PriorDayClose = v; RecalculateLimits(); RecalculateBuffers(); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_HWM")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v >= 0) { Manual_HighWaterMark = v; RecalculateLimits(); RecalculateBuffers(); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_SBal")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0) { Manual_StartingBalance = v; WorkingAccountSize = v; RecalculateLimits(); RecalculateBuffers(); }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "SET_EDIT_NewsPre")
      {
         int v = (int)StringToInteger(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v >= 0) Runtime_NewsPreMinutes = v;
