      if(sparam == "SET_EDIT_Scale")
      {
         double v = StringToDouble(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v > 0.1)
         {
            Runtime_GuiScale = v; Runtime_UseAutoScaling = false;
            ObjectsDeleteAll(0); CreateTransparentPanel(); UpdateMonitorGUI();
            SettingsPanelExpanded = false; ToggleSettingsPanel();
         }
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "GUI_EDIT_SL")
      {
         int v = (int)StringToInteger(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v >= 0) Runtime_SL_Pips = v;
         g_active_edit_object = ""; ChartRedraw();
      }
      if(sparam == "GUI_EDIT_TP")
      {
         int v = (int)StringToInteger(ObjectGetString(0, sparam, OBJPROP_TEXT));
         if(v >= 0) Runtime_TP_Pips = v;
         g_active_edit_object = ""; ChartRedraw();
