      pdc = PriorDayClose;         // fall back to auto
   }
   double hwm = (Manual_HighWaterMark  > 0) ? Manual_HighWaterMark  : HighWaterMark;
   double bal = (Manual_StartingBalance > 0) ? Manual_StartingBalance : WorkingAccountSize;

   StartingBalance    = bal;
